"use client";

import { useState } from "react";
import type { Key } from "react-aria-components";
import { Listbox } from "~/registry/ui/list-box";
import { Popover } from "~/registry/ui/popover";

import { Select } from "~/registry/ui/select";

const fruits = [
  {
    id: 1,
    name: "Apple",
  },
  {
    id: 2,
    name: "Banana",
  },
  {
    id: 3,
    name: "Blueberry",
  },
  {
    id: 4,
    name: "Orange",
  },
  {
    id: 5,
    name: "Strawberry",
  },
  {
    id: 6,
    name: "Grapes",
  },
  {
    id: 7,
    name: "Mango",
  },
];

export function SelectUnselectableDemo() {
  const [fruit, setFruit] = useState<Key | null>(null);

  function handleSelectionChange(key: Key | Key[] | null) {
    if (Array.isArray(key)) {
      return;
    }

    setFruit(key === fruit ? null : key);
  }

  return (
    <Select.Root
      aria-label="Fruits"
      onChange={handleSelectionChange}
      placeholder="Select a fruit"
      value={fruit}
    >
      <Select.Trigger className="w-44">
        <Select.Value />
      </Select.Trigger>

      <Popover.Content>
        <Listbox.Root items={fruits}>
          {(item) => (
            <Listbox.Item id={item.id} textValue={item.name}>
              {item.name}
            </Listbox.Item>
          )}
        </Listbox.Root>
      </Popover.Content>
    </Select.Root>
  );
}
